<section class="single-herbs-guide__section" aria-labelledby="topic-eight-foundations"><h4 id="topic-eight-foundations"><?php echo s($summertext('Herbs That Clear Summer Heat: general introduction', 'Hierbas que aclaran Calor de Verano: introducción general')); ?></h4><p class="single-herbs-guide__section-lead"><?php echo s($summertext('Summerheat rises and disperses, consumes Qi and fluids, and often combines with Dampness. Board questions turn on thirst, irritability, heaviness, digestive upset and the route used to clear Heat.', 'Calor de Verano asciende y dispersa, consume Qi y líquidos y suele combinarse con Humedad. Las preguntas Board dependen de sed, irritabilidad, pesadez, trastorno digestivo y la vía utilizada para aclarar Calor.')); ?></p><div class="single-herbs-guide__pattern"><article><strong><?php echo s($summertext('Heat-dominant', 'Predominio de Calor')); ?></strong><span><?php echo s($summertext('Fever, profuse sweating, thirst, irritability and scanty dark urine.', 'Fiebre, sudor profuso, sed, irritabilidad y orina oscura escasa.')); ?></span></article><article><strong><?php echo s($summertext('Dampness-dominant', 'Predominio de Humedad')); ?></strong><span><?php echo s($summertext('Heaviness, nausea, chest or epigastric oppression, poor appetite and diarrhea.', 'Pesadez, náusea, opresión torácica o epigástrica, poco apetito y diarrea.')); ?></span></article><article><strong><?php echo s($summertext('Choose the exit', 'Elige la salida')); ?></strong><span><?php echo s($summertext('Vent aromatically, raise clear Yang, generate fluids, clear Heart Fire or drain through urine.', 'Exteriorizar aromáticamente, elevar Yang claro, generar líquidos, aclarar Fuego de Corazón o drenar por orina.')); ?></span></article></div><p class="single-herbs-guide__scope-note"><strong><?php echo s($summertext('General precautions:', 'Precauciones generales:')); ?></strong> <?php echo s($summertext('cold and fluid-draining herbs may weaken the Spleen or further deplete fluids. Match Heat versus Dampness instead of treating all warm-weather symptoms identically.', 'las hierbas frías y drenantes pueden debilitar Bazo o agotar más líquidos. Distingue Calor de Humedad en vez de tratar igual todos los síntomas de clima cálido.')); ?></p><aside class="single-herbs-guide__memory-path" aria-label="<?php echo s($summertext('Summer house memory path', 'Recorrido mnemotécnico de la casa en verano')); ?>"><p class="single-herbs-guide__memory-line"><?php echo s($summertext('A heatwave reaches the study house. Six cooling stations solve six different problems.', 'Una ola de calor llega a la casa de estudio. Seis estaciones refrescantes resuelven seis problemas distintos.')); ?></p><p><?php echo s($summertext('Qing Hao opens the skylight; He Ye raises the lotus roof; Xi Gua Pi refills the cooler; Lian Zi Xin shuts off the Heart alarm; Lu Gen restores the Lung-Stomach water pipe; Dan Zhu Ye carries Heat to the urinary drain.', 'Qing Hao abre la claraboya; He Ye eleva el techo de loto; Xi Gua Pi rellena el enfriador; Lian Zi Xin apaga la alarma de Corazón; Lu Gen restaura la tubería Pulmón-Estómago; Dan Zhu Ye lleva Calor al desagüe urinario.')); ?></p><p><strong><?php echo s($summertext('Same heatwave, different cooling station.', 'Misma ola de calor, distinta estación refrescante.')); ?></strong></p></aside><h5 class="single-herbs-guide__catalog-heading"><?php echo s($summertext('Current module herbs', 'Hierbas del módulo vigente')); ?></h5><p class="single-herbs-guide__catalog-intro"><?php echo s($summertext('Study these six in the module sequence. Xi Gua Pi is visibly flagged because it is absent from the current Appendix A.', 'Estudia estas seis en la secuencia del módulo. Xi Gua Pi se señala visiblemente porque está ausente del Appendix A vigente.')); ?></p><ol class="single-herbs-guide__category-herbs"><?php foreach ($summerherbs as $categoryherb): ?><li class="single-herbs-guide__category-herb single-herbs-guide__category-herb--core"><div class="single-herbs-guide__category-herb-head"><strong><?php echo s($categoryherb['name']); ?></strong><em><?php echo s($categoryherb['latin']); ?></em><span class="single-herbs-guide__category-herb-badge<?php echo $categoryherb['official'] ? '' : ' single-herbs-guide__category-herb-badge--outside'; ?>"><?php echo s($categoryherb['official'] ? $summertext('Module + current Appendix A', 'Módulo + Appendix A vigente') : $summertext('Module only · outside current Appendix A', 'Solo módulo · fuera del Appendix A vigente')); ?></span></div><p><?php echo s($categoryherb['identity']); ?></p></li><?php endforeach; ?></ol><div class="single-herbs-guide__annex"><h5 class="single-herbs-guide__catalog-heading"><?php echo s($summertext('Annex · Additional official Summerheat recognition', 'Anexo · Reconocimiento oficial adicional para Calor de Verano')); ?></h5><p class="single-herbs-guide__catalog-intro"><?php echo s($summertext('These current Appendix A substances broaden recognition without changing the six-item module sequence.', 'Estas sustancias del Appendix A vigente amplían reconocimiento sin cambiar la secuencia de seis elementos del módulo.')); ?></p><ol class="single-herbs-guide__category-herbs"><?php foreach ($summerannex as $categoryherb): ?><li class="single-herbs-guide__category-herb"><div class="single-herbs-guide__category-herb-head"><strong><?php echo s($categoryherb['name']); ?></strong><em><?php echo s($categoryherb['latin']); ?></em><span class="single-herbs-guide__category-herb-badge"><?php echo s($summertext('In current Appendix A', 'En el Appendix A vigente')); ?></span></div><p><?php echo s($categoryherb['note']); ?></p></li><?php endforeach; ?></ol></div></section>

<section class="single-herbs-guide__section" aria-labelledby="topic-eight-yang-title"><h4 id="topic-eight-yang-title"><?php echo s($summertext('Yang comparative fingerprint', 'Huella comparativa de Yang')); ?></h4><p class="single-herbs-guide__section-lead"><?php echo s($summertext('Selected Chapter 3 bars show that the group is not interchangeable. Values are relative study indices, not clinical percentages.', 'Barras seleccionadas del capítulo 3 muestran que el grupo no es intercambiable. Los valores son índices relativos de estudio, no porcentajes clínicos.')); ?></p><div class="single-herbs-guide__yang-charts"><?php foreach ($summercharts as $chart): ?><article class="single-herbs-guide__yang-chart"><h5><?php echo s($chart['title']); ?></h5><small><?php echo s($chart['figure']); ?></small><?php foreach ($chart['items'] as $herbname => $value): ?><div class="single-herbs-guide__yang-bar"><span><?php echo s($herbname); ?></span><span class="single-herbs-guide__yang-bar-track"><span class="single-herbs-guide__yang-bar-fill" style="width:<?php echo (int) $value; ?>%"></span></span><b><?php echo (int) $value; ?></b></div><?php endforeach; ?></article><?php endforeach; ?></div><p class="single-herbs-guide__yang-note"><strong><?php echo s($summertext('Reading rule:', 'Regla de lectura:')); ?></strong> <?php echo s($summertext('Do not memorize “all cool Summerheat.” Memorize the destination: latent Heat, Spleen, Heart, Lung/Stomach fluids or Small-Intestine urine.', 'No memorices “todas refrescan Calor de Verano”. Memoriza el destino: Calor latente, Bazo, Corazón, líquidos Pulmón/Estómago u orina de Intestino Delgado.')); ?></p></section>

